   276	  // return (valclass instanceof reflcass)
   277	  public boolean instanceOf(String valclass, String refclass) {
   278	    if (refclass == null || valclass == null) {
   279	      return false;
   280	    }
   281	
   282	    if (valclass.equals(refclass)) {
   283	      return true;
   284	    }
   285	
   286	    StructClass cl = this.getClass(valclass);
   287	    // Don't know what we are? We must at least be an object.
   288	    if ((cl == null || cl.superClass == null) && refclass.equals("java/lang/Object")) {
   289	      return true;
   290	    }
   291	
   292	    if (cl == null) {
   293	      return false;
   294	    }
   295	
   296	    if (cl.superClass != null && this.instanceOf(cl.superClass.getString(), refclass)) {
   297	      return true;
   298	    }
   299	
   300	    for (int iface : cl.getInterfaces()) {
   301	      if (this.instanceOf(cl.getPool().getPrimitiveConstant(iface).getString(), refclass)) {
   302	        return true;
   303	      }
   304	    }
   305	
   306	    return false;
   307	  }
   308	
   309	  // JOIN both classes on the lattice. Find a common ancestor.
   310	  public @Nullable StructClass findCommonAncestor(String classA, String classB) {
   311	    StructClass a = this.getClass(classA);
   312	    StructClass b = this.getClass(classB);
   313	
   314	    if (a == null || b == null) {
   315	      return null;
   316	    }
   317	
   318	    if (instanceOf(classB, classA)) {
   319	      return a;
   320	    }
   321	
   322	    // Iterate through the superclasses and interfaces to find any that can be assigned.
   323	    // Don't return if the returned class is Object, otherwise we may miss out on other opportunities to do better
   324	    // The returned type is essentially arbitrary; extended superclasses are preferred before interfaces.
   325	
   326	    if (a.superClass != null) {
   327	      StructClass cl = findCommonAncestor(a.superClass.getString(), classB);
   328	      if (cl != null && !cl.qualifiedName.equals("java/lang/Object")) {
   329	        return cl;
   330	      }
   331	    }
   332	
   333	    for (int iface : a.getInterfaces()) {
   334	      StructClass cl = findCommonAncestor(a.getPool().getPrimitiveConstant(iface).getString(), classB);
   335	      if (cl != null && !cl.qualifiedName.equals("java/lang/Object")) {
   336	        return cl;
   337	      }
   338	    }
   339	
   340	    return null;
   341	  }
