     9	public class OptionParser {
    10	  private static final Map<String, String> SHORT_TO_LONG_NAME_MAP = new HashMap<>();
    11	
    12	  private static final String[] CUSTOM_CHECKS = {
    13	    "-e=",
    14	    "--add-external=",
    15	    "-only=",
    16	    "--only=",
    17	    "-s",
    18	    "--silent"
    19	  };
    20	
    21	  public static boolean parse(String arg, Map<String, Object> options) {
    22	    for (String check : CUSTOM_CHECKS) {
    23	      if (arg.startsWith(check)) {
    24	        return false;
    25	      }
    26	    }
    27	
    28	    if (!arg.startsWith("--")) {
    29	      parseShort(arg, options);
    30	      return true;
    31	    }
    32	
    33	    arg = arg.substring(2);
    34	    int index = arg.indexOf('=');
    35	    if (index == -1) {
    36	      if (arg.startsWith("no-")) {
    37	        options.put(arg.substring(3), "0");
    38	      } else {
    39	        options.put(arg, "1");
    40	      }
    41	    } else {
    42	      String key = arg.substring(0, index);
    43	      String value = arg.substring(index + 1);
    44	      if ("true".equalsIgnoreCase(value)) {
    45	        value = "1";
    46	      } else if ("false".equalsIgnoreCase(value)) {
    47	        value = "0";
    48	      }
    49	
    50	      options.put(key, value);
    51	    }
    52	    return true;
    53	  }
    54	
    55	  public static void parseShort(String arg, Map<String, Object> options) {
    56	    if (SHORT_TO_LONG_NAME_MAP.isEmpty()) {
    57	      mapShortToLongNames();
    58	    }
    59	
    60	    String shortName = arg.substring(1, 4);
    61	    String value = arg.substring(5);
    62	    String longName = SHORT_TO_LONG_NAME_MAP.get(shortName);
    63	    if (longName == null) {
    64	      longName = shortName;
    65	    }
    66	    parse("--" + longName + "=" + value, options);
    67	  }
    68	
    69	  private static void mapShortToLongNames() {
    70	    for (Field field : IFernflowerPreferences.class.getDeclaredFields()) {
    71	      IFernflowerPreferences.ShortName shortName = field.getAnnotation(IFernflowerPreferences.ShortName.class);
    72	      if (shortName != null) {
    73	        try {
    74	          SHORT_TO_LONG_NAME_MAP.put(shortName.value(), (String) field.get(null));
    75	        } catch (IllegalAccessException e) {
    76	          throw new RuntimeException(e);
    77	        }
    78	      }
    79	    }
    80	
    81	    // Hardcode old JAD varnaming from the plugin
    82	    SHORT_TO_LONG_NAME_MAP.put("jvn", "jad-style-variable-naming");
    83	    SHORT_TO_LONG_NAME_MAP.put("jpr", "jad-style-parameter-naming");
    84	  }
    85	}

