  private Map<String, byte[]> compile(String directory, String className, String source) throws IOException {
    Path sourceRoot = tempDir.resolve(directory).resolve("src");
    Path outputRoot = tempDir.resolve(directory).resolve("out");
    Path sourceFile = sourceRoot.resolve(className.replace('.', '/') + ".java");
    Files.createDirectories(sourceFile.getParent());
    Files.createDirectories(outputRoot);
    Files.writeString(sourceFile, source);

    JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
    assertNotNull(compiler, "Tests require a JDK");
    assertEquals(0, compiler.run(null, null, null, "-d", outputRoot.toString(), sourceFile.toString()));

