   288	  private @Nullable ClassCandidate resolveCandidate(String name) {
   289	    ClassCandidate cached = this.selections.get(name);
   290	    if (cached != null) {
   291	      return cached;
   292	    }
   293	
   294	    ensureFamilyIndex();
   295	    List<ClassCandidate> eligible = getEligibleCandidates(name);
   296	    if (eligible.isEmpty()) {
   297	      return null;
   298	    }
   299	
   300	    ClassFamily family = this.families.get(name);
   301	    if (family != null && eligible.get(0).unit.isOwn()) {
   302	      ClassCandidate anchor = resolveFamilyAnchor(family);
   303	      cached = this.selections.get(name);
   304	      if (cached != null) {
   305	        return cached;
   306	      }
   307	
   308	      for (ClassCandidate candidate : eligible) {
   309	        if (candidate.unit == anchor.unit) {
   310	          logDifferingSelection(name, eligible, candidate, family.root);
   311	          this.selections.put(name, candidate);
   312	          return candidate;
   313	        }
   314	      }
   315	
   316	      throw new IllegalStateException(
   317	        "Class family origin conflict for root " + family.root + ": member " + name +
   318	          " is anchored to " + anchor.unit.getOriginDescription() +
   319	          " but is available only from own origins " + describeOrigins(eligible)
   320	      );
   321	    }
   322	
   323	    ClassCandidate selected = selectByStrategy(name, eligible, family == null ? name : family.root);
   324	    this.selections.put(name, selected);
   325	    return selected;
   326	  }
