   328	  private List<ClassCandidate> getEligibleCandidates(String name) {
   329	    LinkedHashMap<ContextUnit, ClassCandidate> byOrigin = this.candidates.get(name);
   330	    List<ClassCandidate> registered = byOrigin == null ? List.of() : new ArrayList<>(byOrigin.values());
   331	    List<ClassCandidate> own = registered.stream().filter(candidate -> candidate.unit.isOwn()).toList();
   332	    if (!own.isEmpty()) {
   333	      return loadableCandidates(name, own);
   334	    }
   335	
   336	    for (ContextUnit lazyUnit : this.lazyUnits) {
   337	      probeLazyCandidate(name, lazyUnit);
   338	    }
   339	
   340	    byOrigin = this.candidates.get(name);
   341	    if (byOrigin == null) {
   342	      return List.of();
   343	    }
   344	    return loadableCandidates(name, byOrigin.values().stream().filter(candidate -> !candidate.unit.isOwn()).toList());
   345	  }
