   424	  private void ensureFamilyIndex() {
   425	    if (this.familyIndexInitialized) {
   426	      return;
   427	    }
   428	    this.familyIndexInitialized = true;
   429	
   430	    List<String> duplicateNames = this.candidates.entrySet().stream()
   431	      .filter(entry -> entry.getValue().keySet().stream().filter(ContextUnit::isOwn).count() > 1)
   432	      .map(Map.Entry::getKey)
   433	      .toList();
   434	    if (duplicateNames.isEmpty()) {
   435	      return;
   436	    }
   437	
   438	    Map<String, String> parents = new LinkedHashMap<>();
   439	    Map<String, LinkedHashSet<String>> links = new LinkedHashMap<>();
   440	    for (Map.Entry<String, LinkedHashMap<ContextUnit, ClassCandidate>> entry : this.candidates.entrySet()) {
   441	      for (ClassCandidate candidate : entry.getValue().values()) {
   442	        if (!candidate.unit.isOwn()) {
   443	          continue;
   444	        }
   445	        StructClass clazz = candidate.getStructClass();
   446	        if (clazz == null) {
   447	          continue;
   448	        }
   449	
   450	        links.computeIfAbsent(clazz.qualifiedName, ignored -> new LinkedHashSet<>());
   451	        StructInnerClassesAttribute innerClasses = clazz.getAttribute(StructGeneralAttribute.ATTRIBUTE_INNER_CLASSES);
   452	        if (innerClasses != null) {
   453	          for (StructInnerClassesAttribute.Entry inner : innerClasses.getEntries()) {
   454	            if (inner.enclosingName != null) {
   455	              addFamilyLink(inner.innerName, inner.enclosingName, parents, links);
   456	            }
   457	          }
   458	        }
   459	
   460	        StructEnclosingMethodAttribute enclosingMethod = clazz.getAttribute(StructGeneralAttribute.ATTRIBUTE_ENCLOSING_METHOD);
   461	        if (enclosingMethod != null) {
   462	          addFamilyLink(clazz.qualifiedName, enclosingMethod.getClassName(), parents, links);
   463	        }
   464	      }
   465	    }
   466	
   467	    Set<String> indexed = new HashSet<>();
   468	    for (String duplicateName : duplicateNames) {
   469	      if (indexed.contains(duplicateName)) {
   470	        continue;
   471	      }
   472	
   473	      LinkedHashSet<String> members = collectFamilyMembers(duplicateName, links);
   474	      String root = findFamilyRoot(duplicateName, members, parents);
   475	      String anchorDuplicate = duplicateNames.stream().filter(members::contains).findFirst().orElse(duplicateName);
   476	      ClassFamily family = new ClassFamily(root, anchorDuplicate);
   477	      for (String member : members) {
   478	        this.families.put(member, family);
   479	      }
   480	      indexed.addAll(members);
   481	    }
   482	  }
