   495	  private static LinkedHashSet<String> collectFamilyMembers(String start, Map<String, LinkedHashSet<String>> links) {
   496	    LinkedHashSet<String> members = new LinkedHashSet<>();
   497	    ArrayDeque<String> pending = new ArrayDeque<>();
   498	    pending.add(start);
   499	    while (!pending.isEmpty()) {
   500	      String member = pending.removeFirst();
   501	      if (!members.add(member)) {
   502	        continue;
   503	      }
   504	      pending.addAll(links.getOrDefault(member, new LinkedHashSet<>()));
   505	    }
   506	    return members;
   507	  }
