   509	  private static String findFamilyRoot(String fallback, Set<String> members, Map<String, String> parents) {
   510	    List<String> roots = members.stream()
   511	      .filter(member -> !members.contains(parents.get(member)))
   512	      .sorted()
   513	      .toList();
   514	    return roots.isEmpty() ? fallback : roots.get(0);
   515	  }
